    "id": "egypt_m6",
    "order": 1006,
    "titleEn": "Map of the Universe",
    "titleEs": "Mapa del Universo: La Tumba de Senenmut",
    "badge": "Stellar Cartographer",
    "badgeEs": "CartÃ³grafo Estelar",
    "badgeIcon": "/assets/egypt/m6_senenmut.png",
